// The workbook omits three additional playable cities. Scale comparable markets
// with the game's published city wage and housing-cost ratios.
for(const [country,city,reference] of [
 ['fr','Нант','Лилль'],['br','Куритиба','Белу-Оризонти'],['br','Флорианополис','Порту-Алегри']
]){
 const local=economyCity97(country,city),base=economyCity97(country,reference);
 const rent=local.rent/base.rent,wage=local.wage/base.wage;
 const scale=(range,factor)=>range.map(value=>Math.round(value*factor));
 businessMarket165[country][city]=Object.fromEntries(Object.entries(businessMarket165[country][reference])
  .map(([key,[r,w,a,o,v,s, demand]])=>[key,[scale(r,rent),scale(w,wage),scale(a,wage),scale(o,wage),v,scale(s,(rent+wage)/2),demand]]));
}
